// Helper: گرفتن اطلاعات آماده‌سازی بر اساس نام ماده
const getPrepInfo = (ingredientName) => {
  if (INGREDIENT_PREP_INFO[ingredientName]) {
    return INGREDIENT_PREP_INFO[ingredientName];
  }
  const normalizedName = ingredientName?.replace(/_/g, ' ');
  for (const key of Object.keys(INGREDIENT_PREP_INFO)) {
    if (key.replace(/_/g, ' ') === normalizedName) {
      return INGREDIENT_PREP_INFO[key];
    }
  }
  return {
    yieldFactor: 1.00,
    rawLabel: ingredientName || 'نامشخص',
    rawRatio: 1.00,
    waterMode: 'none',
    waterRatio: 0,
    waterLabel: '—',
    notes: 'اطلاعات در دسترس نیست.',
    prepNote: '',
  };
};

// Helper: محاسبه وزن خام و آب لازم
// منطق:
//   rawWeight = cookedWeight × rawRatio
//   waterAmount = rawWeight × waterRatio (ml per 1g raw)
const calcRawAndWater = (cookedWeight, ingredientName) => {
  const info = getPrepInfo(ingredientName);
  const rawWeight = Math.round(cookedWeight * info.rawRatio);
  const waterAmount = info.waterRatio > 0 ? Math.round(rawWeight * info.waterRatio) : 0;
  return {
    rawWeight,
    waterAmount,
    rawLabel: info.rawLabel,
    waterLabel: info.waterLabel,
    waterMode: info.waterMode,
    notes: info.notes,
    prepNote: info.prepNote,
  };
};

