const fmt = (n) => Math.round(n || 0).toLocaleString('fa-IR');
const fmtPrice = fmt;

const fmtKg = (grams) => {
  const kg = (Number(grams) || 0) / 1000;
  return kg.toLocaleString('fa-IR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
};

const getStorageKey = (orderId) => `prepListChecked_${orderId}`;

const parseISO = (iso) => {
  if (!iso) return null;
  try {
    const s = iso.endsWith('Z') ? iso : iso + 'Z';
    return new Date(s);
  } catch {
    return null;
  }
};

// فرمت ساعت فارسی از ISO (به زمان ایران UTC+3:30)
const fmtClockFa = (iso) => {
  if (!iso) return '—';
  const d = parseISO(iso);
  if (!d) return '—';
  const tehran = new Date(d.getTime() + (3.5 * 60 * 60 * 1000));
  const h = String(tehran.getUTCHours()).padStart(2, '0');
  const m = String(tehran.getUTCMinutes()).padStart(2, '0');
  // 🐛 FIX: padStart قبل از toFa اعمال می‌شه، ولی toFa(0) = '۰' (تک کاراکتر)
  // پس باید بعد از toFa هم padStart بشه
  return `${toFa(Number(h))}:${toFa(Number(m))}`;
};

// فرمت ساعت از timestamp (میلی‌ثانیه)
// 🐛 FIX: ساعت و دقیقه رو به‌صورت ۲ رقمی فارسی نمایش بده
const fmtClockFromMs = (ms) => {
  if (!ms) return '—';
  const tehran = new Date(ms + (3.5 * 60 * 60 * 1000));
  const h = String(tehran.getUTCHours()).padStart(2, '0');
  const m = String(tehran.getUTCMinutes()).padStart(2, '0');
  // تبدیل به فارسی و padding با '۰'
  const faH = toFa(Number(h));
  const faM = toFa(Number(m));
  return `${faH.length === 1 ? '۰' + faH : faH}:${faM.length === 1 ? '۰' + faM : faM}`;
};

// محاسبه زمان پایان مورد انتظار
const calcEndMs = (startMs, plannedMin, extendedMin = 0) => {
  if (!startMs) return null;
  return startMs + ((plannedMin || 0) + (extendedMin || 0)) * 60 * 1000;
};

// فرمت زمان فارسی — اگه بیشتر از 60 دقیقه باشه، به‌صورت H:MM:SS نشون بده
const fmtMMSSFa = (totalSec) => {
  if (totalSec < 0) totalSec = 0;
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = Math.floor(totalSec % 60);
  if (h > 0) {
    return `${toFa(h)}:${toFa(m).padStart(2, '۰')}:${toFa(s).padStart(2, '۰')}`;
  }
  return `${toFa(m)}:${toFa(s).padStart(2, '۰')}`;
};

// ============================================================
//  Sort Icon
// ============================================================
const SortIcon = ({ columnKey, sortConfig }) => {
  if (sortConfig.key !== columnKey) {
    return <span className="text-ink-300 dark:text-cream-600 text-[10px]">↕</span>;
  }
  return sortConfig.direction === 'ascending' ? (
    <span className="text-ink-700 dark:text-cream-200 text-[10px]">▲</span>
  ) : (
    <span className="text-ink-700 dark:text-cream-200 text-[10px]">▼</span>
  );
};

