function PrepItemCard({ item, index, viewMode, isChecked, onToggleCheck }) {
  const style = getCategoryStyle(item.category);
  return (
    <div className={`bg-white dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-xl shadow-sm relative overflow-hidden ${isChecked ? 'opacity-60' : ''}`}>
      <div className={`absolute right-0 top-0 bottom-0 w-1 ${style.strip}`} aria-hidden="true" />
      <div className="p-3 pr-4">
        <div className="flex items-start gap-2 mb-2">
          <div className="w-6 h-6 rounded-full bg-ink-100 dark:bg-ink-700 flex items-center justify-center text-[10px] font-black text-ink-500 dark:text-cream-400 flex-shrink-0 font-num tabular-nums">{toFa(index + 1)}</div>
          <div className="flex-1 min-w-0">
            <div className={`font-bold text-ink-900 dark:text-cream-100 text-sm flex items-center gap-1.5 ${isChecked ? 'line-through' : ''}`}>
              <span>{style.icon}</span><span className="truncate">{item.name}</span>
            </div>
            {item.english_name && <div className="text-[10px] text-ink-400 dark:text-cream-500 font-mono mt-0.5 truncate" dir="ltr">{item.english_name}</div>}
          </div>
          {viewMode === 'checklist' ? (
            <label className="flex items-center justify-center w-9 h-9 flex-shrink-0 cursor-pointer">
              <input type="checkbox" checked={!!isChecked} onChange={() => onToggleCheck(item.id)} className="w-5 h-5 cursor-pointer accent-ink-700 rounded" />
            </label>
          ) : (
            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-bold border bg-ink-50 dark:bg-ink-700 text-ink-600 dark:text-cream-300 border-ink-200 dark:border-dark-600 flex-shrink-0">{style.label}</span>
          )}
        </div>
        <div className="grid grid-cols-2 gap-2 pt-2 border-t border-ink-100 dark:border-dark-700">
          <div className="text-center">
            <div className="text-[9px] text-ink-500 dark:text-cream-400 font-bold">⚖️ وزن</div>
            <div className="font-bold text-brand-700 dark:text-brand-300 text-xs font-num tabular-nums">{fmt(item.order_weight_g)}g</div>
          </div>
          <div className="text-center border-r border-ink-100 dark:border-dark-700 pr-2">
            <div className="text-[9px] text-ink-500 dark:text-cream-400 font-bold">💵 /kg</div>
            <div className="font-bold text-ink-700 dark:text-cream-200 text-xs font-num tabular-nums">{fmtPrice(item.price_per_kg)}</div>
          </div>
        </div>
        <div className="mt-2 pt-2 border-t border-ink-100 dark:border-dark-700 flex items-center justify-between gap-2">
          <span className="text-[10px] text-ink-500 dark:text-cream-400 font-bold">💰 کل</span>
          <span className="font-bold text-accent-700 dark:text-accent-400 text-sm font-num tabular-nums">{fmtPrice(item.order_price_toman)}</span>
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  کامپوننت اصلی PrepList
// ============================================================
export default function PrepList({ orderData }) {
  const { showToast } = useToast();
  const [viewMode, setViewMode] = useState('kitchen');
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [checkedItems, setCheckedItems] = useState({});
  const [copied, setCopied] = useState(false);
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'ascending' });
  const isInitialLoadRef = useRef(true);
  const [isMobile, setIsMobile] = useState(() => typeof window !== 'undefined' ? window.innerWidth < MOBILE_BREAKPOINT : false);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  const orderId = orderData?.order_id;
  const storageKey = orderId ? getStorageKey(orderId) : null;
  const allItems = useMemo(() => orderData?.recipe_full?.recipe_data || [], [orderData]);
  const activeItems = useMemo(() => allItems.filter(i => !i.is_allergen), [allItems]);
  const allergenItems = useMemo(() => allItems.filter(i => i.is_allergen), [allItems]);

  useEffect(() => {
    if (!storageKey) { setCheckedItems({}); return; }
    isInitialLoadRef.current = true;
    try { const saved = localStorage.getItem(storageKey); setCheckedItems(saved ? JSON.parse(saved) : {}); } catch { setCheckedItems({}); }
  }, [storageKey]);

  useEffect(() => {
    if (!storageKey) return;
    if (isInitialLoadRef.current) { isInitialLoadRef.current = false; return; }
    try { localStorage.setItem(storageKey, JSON.stringify(checkedItems)); } catch {}
  }, [checkedItems, storageKey]);

  useEffect(() => { setSortConfig({ key: null, direction: 'ascending' }); }, [viewMode]);

  const availableCategories = useMemo(() => ['all', ...Array.from(new Set(activeItems.map(i => i.category)))], [activeItems]);
  const filteredItems = useMemo(() => activeItems.filter(item => {
    const matchSearch = !searchQuery || item.name.toLowerCase().includes(searchQuery.toLowerCase()) || (item.english_name || '').toLowerCase().includes(searchQuery.toLowerCase());
    return matchSearch && (categoryFilter === 'all' || item.category === categoryFilter);
  }), [activeItems, searchQuery, categoryFilter]);

  const sortedItems = useMemo(() => {
    let items = [...filteredItems];
    if (sortConfig.key !== null) items.sort((a, b) => (sortConfig.direction === 'ascending' ? (a[sortConfig.key] || 0) - (b[sortConfig.key] || 0) : (b[sortConfig.key] || 0) - (a[sortConfig.key] || 0)));
    return items;
  }, [filteredItems, sortConfig]);

  const handleSort = (key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'ascending' ? 'descending' : 'ascending' }));
  const stats = useMemo(() => {
    const totalWeight = activeItems.reduce((s, i) => s + (i.order_weight_g || 0), 0);
    const totalPrice = activeItems.reduce((s, i) => s + (i.order_price_toman || 0), 0);
    const checkedCount = activeItems.filter(i => checkedItems[i.id]).length;
    return { totalItems: activeItems.length, totalWeight, totalPrice, avgPricePerKg: totalWeight > 0 ? totalPrice / (totalWeight / 1000) : 0, checkedCount, progress: activeItems.length > 0 ? (checkedCount / activeItems.length) * 100 : 0 };
  }, [activeItems, checkedItems]);
  const filteredTotals = useMemo(() => ({ weight: sortedItems.reduce((s, i) => s + (i.order_weight_g || 0), 0), price: sortedItems.reduce((s, i) => s + (i.order_price_toman || 0), 0) }), [sortedItems]);
  const toggleCheck = (id) => setCheckedItems(prev => ({ ...prev, [id]: !prev[id] }));
  const copyToClipboard = async () => {
    const text = `📋 لیست #${toFa(orderId)}\n\n` + sortedItems.map((item, idx) => `${toFa(idx + 1)}. ${item.name} - ${fmt(item.order_weight_g)}g`).join('\n') + `\n\n📊 ${fmt(filteredTotals.weight)}g | 💰 ${fmt(filteredTotals.price)}`;
    try { await navigator.clipboard.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 2000); showToast('success', 'کپی شد'); } catch { showToast('error', 'خطا'); }
  };

  if (!orderData) return (<div className="bg-white dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-xl p-8 text-center" dir="rtl"><div className="text-4xl mb-2 opacity-60">📋</div><div className="font-bold text-ink-700 dark:text-cream-200 mb-1">داده‌ای موجود نیست</div><div className="text-xs text-ink-500 dark:text-cream-400">ابتدا سفارشی انتخاب کنید</div></div>);
  const currentTab = VIEW_TABS.find(t => t.id === viewMode) || VIEW_TABS[0];

  return (
    <div className="space-y-2.5" dir="rtl">
      <div className="bg-ink-900 dark:bg-ink-950 text-white rounded-xl p-3 sm:p-4">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
          <div className="flex items-center gap-2 min-w-0">
            <span className="text-lg flex-shrink-0">{currentTab.icon}</span>
            <div className="min-w-0"><div className="text-[10px] opacity-70 font-bold">لیست تهیه سفارش</div><div className="font-bold text-sm truncate">#{toFa(orderId)} — {currentTab.label}</div></div>
          </div>
          {viewMode !== 'kitchen' && (
            <div className="flex gap-2 text-[10px]">
              <div className="bg-white/10 rounded px-2 py-1 text-center"><div className="opacity-70">مواد</div><div className="font-bold tabular-nums">{toFa(stats.totalItems)}</div></div>
              <div className="bg-white/10 rounded px-2 py-1 text-center"><div className="opacity-70">وزن</div><div className="font-bold tabular-nums">{fmtKg(stats.totalWeight)}kg</div></div>
              <div className="bg-white/10 rounded px-2 py-1 text-center"><div className="opacity-70">هزینه</div><div className="font-bold tabular-nums">{fmtPrice(stats.totalPrice)}</div></div>
            </div>
          )}
        </div>
      </div>

      <div className="flex gap-1.5 overflow-x-auto pb-1">
        {VIEW_TABS.map(tab => (
          <button key={tab.id} onClick={() => setViewMode(tab.id)} className={`flex items-center gap-1.5 px-3 py-2 rounded-lg font-bold text-xs whitespace-nowrap transition-all min-h-[40px] ${viewMode === tab.id ? 'bg-ink-900 dark:bg-cream-100 text-white dark:text-ink-900' : 'bg-white dark:bg-ink-800 text-ink-600 dark:text-cream-300 border border-ink-200 dark:border-dark-700 hover:bg-ink-50 dark:hover:bg-ink-700'}`}>
            <span>{tab.icon}</span><span>{tab.label}</span>
          </button>
        ))}
      </div>

      {viewMode === 'kitchen' && <KitchenMode orderId={orderId} showToast={showToast} />}

      {viewMode !== 'kitchen' && (
        <>
          <div className="bg-white dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-xl p-2.5 space-y-2">
            <div className="flex flex-col sm:flex-row gap-2">
              <input type="text" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} placeholder="🔍 جستجو..." className="flex-1 bg-ink-50 dark:bg-ink-700 border border-ink-200 dark:border-dark-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-ink-400" />
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="bg-ink-50 dark:bg-ink-700 border border-ink-200 dark:border-dark-700 rounded-lg px-2 py-2 text-sm focus:outline-none">
                {availableCategories.map(cat => <option key={cat} value={cat}>{cat === 'all' ? 'همه' : cat}</option>)}
              </select>
              <button onClick={copyToClipboard} className="bg-ink-700 hover:bg-ink-800 text-white text-xs font-bold py-2 px-3 rounded-lg">{copied ? '✅' : '📋 کپی'}</button>
            </div>
            {viewMode === 'checklist' && (
              <div className="flex gap-1.5">
                <button onClick={() => { const all = {}; activeItems.forEach(i => { all[i.id] = true; }); setCheckedItems(all); }} className="flex-1 bg-ink-700 hover:bg-ink-800 text-white text-[11px] font-bold py-1.5 rounded-lg">✅ همه</button>
                <button onClick={() => setCheckedItems({})} className="flex-1 bg-ink-100 dark:bg-ink-700 hover:bg-ink-200 dark:hover:bg-ink-600 text-ink-700 dark:text-cream-200 text-[11px] font-bold py-1.5 rounded-lg">❌ پاک</button>
                <button onClick={() => window.confirm('ریست؟') && setCheckedItems({})} className="bg-rose-100 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300 text-[11px] font-bold py-1.5 px-2 rounded-lg">🔄</button>
              </div>
            )}
          </div>
          {isMobile ? (
            <div className="grid grid-cols-1 gap-2">{sortedItems.map((item, idx) => <PrepItemCard key={item.id} item={item} index={idx} viewMode={viewMode} isChecked={!!checkedItems[item.id]} onToggleCheck={toggleCheck} />)}</div>
          ) : (
            <DesktopTable items={sortedItems} viewMode={viewMode} checkedItems={checkedItems} toggleCheck={toggleCheck} sortConfig={sortConfig} handleSort={handleSort} />
          )}
          <div className="bg-white dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-xl p-3 flex items-center justify-between flex-wrap gap-2 text-xs">
            <span className="font-bold text-ink-800 dark:text-cream-200">جمع کل</span>
            <div className="flex gap-4">
              <span className="text-ink-600 dark:text-cream-300">📦 {toFa(sortedItems.length)}</span>
              <span className="text-brand-700 dark:text-brand-300 font-bold tabular-nums">{fmt(filteredTotals.weight)}g</span>
              <span className="text-accent-700 dark:text-accent-400 font-bold tabular-nums">{fmtPrice(filteredTotals.price)}</span>
            </div>
          </div>
          {allergenItems.length > 0 && <div className="bg-rose-50 dark:bg-rose-500/10 border border-rose-200 dark:border-rose-500/30 rounded-xl p-2.5 text-[11px] text-rose-700 dark:text-rose-300 font-bold">🚫 {toFa(allergenItems.length)} ماده حذف‌شده: {allergenItems.map(i => i.name).join('، ')}</div>}
        </>
      )}
    </div>
  );
}

// ============================================================
//  Desktop Table
// ============================================================
function DesktopTable({ items, viewMode, checkedItems, toggleCheck, sortConfig, handleSort }) {
  return (
    <div className="bg-white dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-xl overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-ink-50 dark:bg-ink-700 text-ink-600 dark:text-cream-300 text-[11px]">
              <th className="px-2 py-2 text-center w-10">#</th>
              {viewMode === 'checklist' && <th className="px-2 py-2 text-center w-10">✓</th>}
              <th className="px-2 py-2 text-right cursor-pointer hover:bg-ink-100 dark:hover:bg-ink-600" onClick={() => handleSort('name')}><div className="flex items-center gap-1">نام <SortIcon columnKey="name" sortConfig={sortConfig} /></div></th>
              <th className="px-2 py-2 text-center">دسته</th>
              <th className="px-2 py-2 text-center cursor-pointer hover:bg-ink-100 dark:hover:bg-ink-600" onClick={() => handleSort('order_weight_g')}><div className="flex items-center justify-center gap-1">وزن <SortIcon columnKey="order_weight_g" sortConfig={sortConfig} /></div></th>
              <th className="px-2 py-2 text-center cursor-pointer hover:bg-ink-100 dark:hover:bg-ink-600" onClick={() => handleSort('price_per_kg')}><div className="flex items-center justify-center gap-1">قیمت/kg <SortIcon columnKey="price_per_kg" sortConfig={sortConfig} /></div></th>
              <th className="px-2 py-2 text-center cursor-pointer hover:bg-ink-100 dark:hover:bg-ink-600" onClick={() => handleSort('order_price_toman')}><div className="flex items-center justify-center gap-1">کل <SortIcon columnKey="order_price_toman" sortConfig={sortConfig} /></div></th>
            </tr>
          </thead>
          <tbody>
            {items.map((item, idx) => {
              const style = getCategoryStyle(item.category);
              const isChecked = !!checkedItems[item.id];
              return (
                <tr key={item.id} className={`border-t border-ink-100 dark:border-dark-700 ${isChecked ? 'opacity-60' : ''} hover:bg-ink-50 dark:hover:bg-ink-700/30`}>
                  <td className="px-2 py-2 text-center text-[11px] font-bold text-ink-500 dark:text-cream-400 tabular-nums">{toFa(idx + 1)}</td>
                  {viewMode === 'checklist' && <td className="px-2 py-2 text-center"><input type="checkbox" checked={isChecked} onChange={() => toggleCheck(item.id)} className="w-5 h-5 cursor-pointer accent-ink-700 rounded" /></td>}
                  <td className="px-2 py-2 text-right"><div className={`font-bold text-ink-900 dark:text-cream-100 flex items-center gap-1.5 ${isChecked ? 'line-through' : ''}`}><span>{style.icon}</span><span>{item.name}</span></div>{item.english_name && <div className="text-[10px] text-ink-400 dark:text-cream-500 font-mono" dir="ltr">{item.english_name}</div>}</td>
                  <td className="px-2 py-2 text-center"><span className="inline-block px-1.5 py-0.5 rounded text-[10px] font-bold bg-ink-50 dark:bg-ink-700 text-ink-600 dark:text-cream-300">{style.label}</span></td>
                  <td className="px-2 py-2 text-center font-bold text-brand-700 dark:text-brand-300 text-xs tabular-nums">{fmt(item.order_weight_g)}g</td>
                  <td className="px-2 py-2 text-center font-bold text-ink-700 dark:text-cream-200 text-xs tabular-nums">{fmtPrice(item.price_per_kg)}</td>
                  <td className="px-2 py-2 text-center font-bold text-accent-700 dark:text-accent-400 text-xs tabular-nums">{fmtPrice(item.order_price_toman)}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}
