// ============================================================
//  SortIcon — Editorial
// ============================================================
function SortIcon({ columnKey, sortConfig }) {
  if (sortConfig.key !== columnKey) {
    return <SiteImage imageKey="icon_sort" fallback="↕" alt="" className="text-cream-100/40 text-xs mr-1" />;
  }
  return sortConfig.direction === 'asc' ? (
    <SiteImage imageKey="icon_sort_up" fallback="▲" alt="" className="text-cream-50 text-xs mr-1" />
  ) : (
    <SiteImage imageKey="icon_sort_down" fallback="▼" alt="" className="text-cream-50 text-xs mr-1" />
  );
}

