const DATE_PRESETS = [
  { id: 'today', label: 'امروز', icon: '📅', iconKey: 'icon_calendar' },
  { id: 'week', label: 'این هفته', icon: '📆', iconKey: 'icon_calendar' },
  { id: 'month', label: 'این ماه', icon: '🗓️' },
  { id: 'last7', label: '۷ روز', icon: '⏪' },
  { id: 'last30', label: '۳۰ روز', icon: '📉', iconKey: 'icon_chart' },
  { id: 'all', label: 'همه', icon: '🌐', iconKey: 'icon_globe' },
];

function getPresetRange(presetId) {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

  if (presetId === 'all') return { start: null, end: null };
  if (presetId === 'today') return { start: today, end: today };

  if (presetId === 'week') {
    const dow = today.getDay();
    const daysSinceSat = (dow + 1) % 7;
    const start = new Date(today);
    start.setDate(start.getDate() - daysSinceSat);
    return { start, end: today };
  }

  if (presetId === 'month') {
    const pToday = new DateObject({ calendar: persian });
    const startP = new DateObject({ calendar: persian }).setDay(1);
    return { start: startP.toDate(), end: pToday.toDate() };
  }

  if (presetId === 'last7') {
    const start = new Date(today);
    start.setDate(start.getDate() - 6);
    return { start, end: today };
  }

  if (presetId === 'last30') {
    const start = new Date(today);
    start.setDate(start.getDate() - 29);
    return { start, end: today };
  }

  return { start: null, end: null };
}

