// frontend/src/admin/components/ResetData.jsx
// ============================================================
//  🗑️ ResetData — کامپوننت ریست داده‌ها از پنل ادمین
//
//  امکان ریست جداگانه‌ی هر دسته از داده‌ها:
//    - سفارش‌ها + پرداخت‌ها + فیش‌ها
//    - کاربران + سگ‌ها
//    - فقط سگ‌ها
//    - تیکت‌ها
//    - نظرات
//    - اعلان‌ها
//    - مشتری‌های مهمان
//    - همه چیز (ریست کامل)
//
//  هر ریست نیاز به تأیید با تایپ عبارت "RESET" داره.
//  استایل: Tailwind هماهنگ با Settings.jsx
// ============================================================
import React, { useState, useEffect, useCallback, useRef } from 'react';
import axios from '../axiosConfig';
import { toFa } from '../../utils/numbers';

// ============================================================
//  Config — دسته‌بندی‌های ریست
// ============================================================
const CATEGORIES = [
  {
    key: 'orders',
    icon: '📦',
    color: 'brand',
    iconBg: 'bg-brand-100 dark:bg-brand-500/20',
    iconText: 'text-brand-700 dark:text-brand-300',
    border: 'border-brand-200 dark:border-brand-500/30',
    bg: 'bg-brand-50/50 dark:bg-brand-500/10',
  },
  {
    key: 'users',
    icon: '👥',
    color: 'accent',
    iconBg: 'bg-accent-100 dark:bg-accent-500/20',
    iconText: 'text-accent-700 dark:text-accent-300',
    border: 'border-accent-200 dark:border-accent-500/30',
    bg: 'bg-accent-50/50 dark:bg-accent-500/10',
  },
  {
    key: 'dogs',
    icon: '🐕',
    color: 'brand',
    iconBg: 'bg-amber-100 dark:bg-amber-500/20',
    iconText: 'text-amber-700 dark:text-amber-300',
    border: 'border-amber-200 dark:border-amber-500/30',
    bg: 'bg-amber-50/50 dark:bg-amber-500/10',
  },
  {
    key: 'tickets',
    icon: '🎫',
    color: 'brand',
    iconBg: 'bg-cyan-100 dark:bg-cyan-500/20',
    iconText: 'text-cyan-700 dark:text-cyan-300',
    border: 'border-cyan-200 dark:border-cyan-500/30',
    bg: 'bg-cyan-50/50 dark:bg-cyan-500/10',
  },
  {
    key: 'testimonials',
    icon: '⭐',
    color: 'brand',
    iconBg: 'bg-pink-100 dark:bg-pink-500/20',
    iconText: 'text-pink-700 dark:text-pink-300',
    border: 'border-pink-200 dark:border-pink-500/30',
    bg: 'bg-pink-50/50 dark:bg-pink-500/10',
  },
  {
    key: 'notifications',
    icon: '🔔',
    color: 'brand',
    iconBg: 'bg-emerald-100 dark:bg-emerald-500/20',
    iconText: 'text-emerald-700 dark:text-emerald-300',
    border: 'border-emerald-200 dark:border-emerald-500/30',
    bg: 'bg-emerald-50/50 dark:bg-emerald-500/10',
  },
  {
    key: 'customers',
    icon: '👤',
    color: 'brand',
    iconBg: 'bg-ink-100 dark:bg-ink-700/50',
    iconText: 'text-ink-600 dark:text-cream-300',
    border: 'border-ink-200 dark:border-dark-600',
    bg: 'bg-ink-50/50 dark:bg-ink-800/30',
  },
];

const inputCls =
  'w-full px-3 py-2.5 min-h-[48px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition font-mono uppercase tracking-wider';

const getErrorMsg = (err, fallback) => {
  const detail = err?.response?.data?.detail;
  if (typeof detail === 'string') return detail;
  return fallback;
};

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function ResetData({ showToast }) {
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [resetting, setResetting] = useState(null);
  const [confirmInputs, setConfirmInputs] = useState({});
  const [showAllConfirm, setShowAllConfirm] = useState(false);

  // ✅ FIX: ref برای showToast تا از re-render loop جلوگیری بشه
  // showToast از والد Settings میاد و memoize نیست — هر بار والد re-render
  // می‌شه (به‌خاطر polling notifications/stats)، showToast جدید می‌شه.
  // اگه showToast رو مستقیماً در deps useCallback بذاریم، fetchPreview
  // مدام بازسازی می‌شه و useEffect دوباره اجرا می‌شه → صفحه رفرش می‌شه.
  const showToastRef = useRef(showToast);
  showToastRef.current = showToast;

  const fetchPreview = useCallback(async (isRefresh = false) => {
    // ✅ FIX: فقط در بار اول loading=true بشه، در رفرش‌های بعدی فقط refreshing
    if (isRefresh) {
      setRefreshing(true);
    } else {
      setLoading(true);
    }
    try {
      const res = await axios.get('/admin/settings/reset-data/preview');
      setPreview(res.data);
    } catch (err) {
      if (showToastRef.current) {
        showToastRef.current('error', getErrorMsg(err, 'خطا در دریافت آمار داده‌ها'));
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);  // ✅ FIX: deps خالی — fetchPreview فقط یک‌بار ساخته می‌شه

  useEffect(() => {
    fetchPreview();
  }, [fetchPreview]);

  const handleReset = async (category) => {
    const confirmValue = (confirmInputs[category] || '').trim().toUpperCase();

    if (confirmValue !== 'RESET') {
      if (showToastRef.current) {
        showToastRef.current('error', 'برای تأیید، باید عبارت RESET رو دقیق وارد کنی');
      }
      return;
    }

    const categoryLabel = preview?.[category]?.label || category;
    const doubleConfirm = window.confirm(
      `⚠️ هشدار نهایی!\n\n` +
      `در حال ریست کردن «${categoryLabel}» هستی.\n` +
      `این عمل غیرقابل برگشت است!\n\n` +
      `آیا واقعاً مطمئن هستی؟`
    );

    if (!doubleConfirm) return;

    setResetting(category);

    try {
      const res = await axios.post(
        `/admin/settings/reset-data/${category}`,
        { confirm: 'RESET' }
      );

      const msg =
        res.data.message +
        (res.data.deleted_files ? ` (${toFa(res.data.deleted_files)} فایل حذف شد)` : '');

      if (showToastRef.current) {
        showToastRef.current('success', msg);
      }

      setConfirmInputs((prev) => ({ ...prev, [category]: '' }));
      fetchPreview(true);  // ✅ FIX: رفرش بدون loading state
    } catch (err) {
      if (showToastRef.current) {
        showToastRef.current('error', getErrorMsg(err, 'خطا در اجرای ریست'));
      }
    } finally {
      setResetting(null);
    }
  };

  const handleConfirmInputChange = (category, value) => {
    setConfirmInputs((prev) => ({ ...prev, [category]: value }));
  };

  // محاسبه‌ی مجموع رکوردها برای هر دسته
  const getTotalRecords = (categoryData) => {
    if (!categoryData?.counts) return 0;
    return Object.values(categoryData.counts).reduce(
      (a, b) => a + (b || 0),
      0
    );
  };

  // ============================================================
  //  رندر کارت ریست
  // ============================================================
  const renderResetCard = (categoryObj, isDanger = false) => {
    const category = categoryObj.key;
    const data = preview?.[category];
    if (!data) return null;

    const totalRecords = getTotalRecords(data);
    const isResetting = resetting === category;
    const confirmValue = confirmInputs[category] || '';
    const isConfirmValid =
      confirmValue.trim().toUpperCase() === 'RESET';
    const hasData =
      totalRecords > 0 || (data.files_to_delete || 0) > 0;

    // استایل کارت
    const cardBorder = isDanger
      ? 'border-rose-300 dark:border-rose-500/40'
      : categoryObj.border;
    const cardBg = isDanger
      ? 'bg-rose-50/50 dark:bg-rose-500/10'
      : categoryObj.bg;

    return (
      <div
        key={category}
        className={`bg-paper-50 dark:bg-ink-800 border-2 ${cardBorder} rounded-3xl shadow-soft overflow-hidden transition ${
          hasData ? '' : 'opacity-60'
        }`}
      >
        {/* Header */}
        <div className={`px-4 sm:px-5 py-3 sm:py-4 border-b ${cardBorder} ${cardBg} flex items-center gap-3`}>
          <div
            className={`w-10 h-10 sm:w-11 sm:h-11 rounded-2xl ${
              isDanger ? 'bg-rose-500' : categoryObj.iconBg
            } flex items-center justify-center text-lg sm:text-xl flex-shrink-0 ${
              isDanger ? 'text-white shadow-brand' : categoryObj.iconText
            }`}
            aria-hidden="true"
          >
            {data.icon || categoryObj.icon}
          </div>
          <div className="min-w-0 flex-1">
            <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
              {data.label}
            </div>
            <div className="text-[10px] sm:text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 leading-relaxed font-bold break-safe">
              {data.description}
            </div>
          </div>
        </div>

        {/* Body */}
        <div className="p-3 sm:p-5">
          {/* Stats */}
          <div className="bg-paper-100 dark:bg-ink-700/50 rounded-2xl p-3 mb-4">
            <div className="flex flex-wrap gap-x-4 gap-y-2 text-xs">
              {Object.entries(data.counts).map(([table, count]) => (
                <div key={table} className="flex items-center gap-1.5">
                  <span className="text-ink-500 dark:text-cream-400 font-bold">
                    {table}:
                  </span>
                  <strong
                    className={`font-num tabular-nums ${
                      count > 0
                        ? 'text-rose-600 dark:text-rose-400'
                        : 'text-ink-600 dark:text-cream-300'
                    }`}
                  >
                    {toFa(count)}
                  </strong>
                </div>
              ))}
              {data.files_to_delete > 0 && (
                <div className="flex items-center gap-1.5">
                  <span className="text-ink-500 dark:text-cream-400 font-bold">
                    فایل‌ها:
                  </span>
                  <strong className="text-rose-600 dark:text-rose-400 font-num tabular-nums">
                    {toFa(data.files_to_delete)}
                  </strong>
                </div>
              )}
            </div>
          </div>

          {/* Confirm input + button */}
          {hasData ? (
            <div>
              <label className="flex items-center gap-1.5 text-xs font-black text-ink-800 dark:text-cream-200 mb-2">
                <span className="flex-shrink-0" aria-hidden="true">🔐</span>
                <span>
                  برای تأیید، عبارت{' '}
                  <code className="bg-rose-100 dark:bg-rose-500/20 px-1.5 py-0.5 rounded-md font-mono text-rose-700 dark:text-rose-300 text-[11px]">
                    RESET
                  </code>{' '}
                  رو وارد کن:
                </span>
              </label>
              <div className="flex flex-col sm:flex-row gap-2">
                <input
                  type="text"
                  value={confirmValue}
                  onChange={(e) =>
                    handleConfirmInputChange(category, e.target.value)
                  }
                  placeholder="RESET"
                  disabled={isResetting}
                  className={`${inputCls} flex-1 ${
                    isConfirmValid
                      ? 'border-emerald-400 dark:border-emerald-500/50 text-emerald-700 dark:text-emerald-300'
                      : ''
                  }`}
                />
                <button
                  type="button"
                  onClick={() => handleReset(category)}
                  disabled={!isConfirmValid || isResetting}
                  className={`min-h-[48px] px-5 py-2.5 rounded-2xl text-xs font-black transition flex items-center justify-center gap-1.5 touch-target flex-shrink-0 ${
                    !isConfirmValid || isResetting
                      ? 'bg-paper-200 dark:bg-ink-700 text-ink-400 dark:text-cream-500 cursor-not-allowed'
                      : isDanger
                      ? 'bg-rose-600 hover:bg-rose-700 text-white shadow-brand hover:-translate-y-0.5 active:translate-y-0'
                      : 'bg-brand-gradient hover:opacity-95 text-white shadow-brand hover:-translate-y-0.5 active:translate-y-0'
                  }`}
                >
                  {isResetting ? (
                    <>
                      <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      <span>در حال ریست...</span>
                    </>
                  ) : (
                    <>
                      <span aria-hidden="true">🗑️</span>
                      <span>ریست</span>
                    </>
                  )}
                </button>
              </div>
            </div>
          ) : (
            <div className="bg-emerald-50 dark:bg-emerald-500/15 border border-emerald-200 dark:border-emerald-500/30 rounded-2xl p-3 text-center text-emerald-700 dark:text-emerald-300 text-xs font-black">
              ✅ هیچ داده‌ای برای ریست وجود نداره
            </div>
          )}
        </div>
      </div>
    );
  };

  // ============================================================
  //  Loading state
  // ============================================================
  if (loading) {
    return (
      <div className="max-w-5xl mx-auto p-3 sm:p-4 space-y-3 sm:space-y-4" dir="rtl">
        <div className="h-32 bg-paper-200 dark:bg-ink-700 rounded-3xl animate-pulse" />
        <div className="h-48 bg-paper-200 dark:bg-ink-700 rounded-3xl animate-pulse" />
        <div className="h-48 bg-paper-200 dark:bg-ink-700 rounded-3xl animate-pulse" />
      </div>
    );
  }

  // ============================================================
  //  رندر اصلی
  // ============================================================
  return (
    <div
      className="max-w-5xl mx-auto p-3 sm:p-4 space-y-3 sm:space-y-4"
      dir="rtl"
    >
      {/* Hero Header — هشدار */}
      <div className="bg-amber-900 dark:bg-amber-950 text-amber-50 rounded-3xl shadow-editorial relative overflow-hidden noise-overlay border-2 border-amber-700 dark:border-amber-800">
        <div
          className="absolute -top-16 -left-16 w-48 h-48 bg-amber-500/20 rounded-full"
          aria-hidden="true"
        />
        <div
          className="absolute -bottom-20 -right-20 w-64 h-64 bg-amber-500/10 rounded-full"
          aria-hidden="true"
        />
        <div className="relative p-4 sm:p-6">
          <div className="flex flex-wrap items-center gap-3 sm:gap-4 mb-3">
            <div
              className="w-12 h-12 sm:w-14 sm:h-14 rounded-3xl bg-amber-500 flex items-center justify-center text-2xl sm:text-3xl flex-shrink-0 shadow-brand"
              aria-hidden="true"
            >
              ⚠️
            </div>
            <div className="min-w-0">
              <h1 className="font-display font-black text-lg sm:text-xl md:text-2xl tracking-tightest">
                ریست داده‌ها
              </h1>
              <p className="text-[11px] sm:text-xs text-amber-200/80 mt-1 leading-relaxed font-bold">
                پاک کردن داده‌های تستی — این عمل غیرقابل برگشت است
              </p>
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 sm:gap-3">
            <div className="bg-white/10 backdrop-blur rounded-2xl px-2 sm:px-3 py-2 sm:py-2.5 text-center border border-white/15">
              <div className="text-[10px] text-amber-200 mb-0.5 font-black">
                📦 دسته‌ها
              </div>
              <div className="font-display font-black text-sm sm:text-base font-num tabular-nums">
                {toFa(CATEGORIES.length + 1)}
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur rounded-2xl px-2 sm:px-3 py-2 sm:py-2.5 text-center border border-white/15">
              <div className="text-[10px] text-amber-200 mb-0.5 font-black">
                🔒 تأیید
              </div>
              <div className="font-display font-black text-xs sm:text-sm">
                دو مرحله‌ای
              </div>
            </div>
            <div className="bg-white/10 backdrop-blur rounded-2xl px-2 sm:px-3 py-2 sm:py-2.5 text-center border border-white/15 col-span-2 sm:col-span-1">
              <div className="text-[10px] text-amber-200 mb-0.5 font-black">
                🛡️ سیستم‌دیتا
              </div>
              <div className="font-display font-black text-xs sm:text-sm">
                حفظ می‌شه
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Refresh button */}
      <div className="flex justify-end">
        <button
          type="button"
          onClick={() => fetchPreview(true)}
          disabled={refreshing}
          className="min-h-[40px] px-4 py-2 bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 hover:bg-paper-100 dark:hover:bg-ink-700 active:bg-paper-200 dark:active:bg-ink-600 text-ink-700 dark:text-cream-200 rounded-2xl text-xs font-black transition flex items-center gap-1.5 touch-target disabled:opacity-50 disabled:cursor-wait"
        >
          {refreshing ? (
            <>
              <span className="inline-block w-3.5 h-3.5 border-2 border-ink-400 border-t-transparent rounded-full animate-spin" />
              <span>در حال بروزرسانی...</span>
            </>
          ) : (
            <>
              <span aria-hidden="true">🔄</span>
              <span>بروزرسانی آمار</span>
            </>
          )}
        </button>
      </div>

      {/* ریست دسته‌ای */}
      <div>
        <h2 className="font-display font-black text-base sm:text-lg text-ink-800 dark:text-cream-100 mb-3 sm:mb-4 flex items-center gap-2">
          <span aria-hidden="true">📋</span>
          <span>ریست دسته‌ای</span>
        </h2>
        <div className="grid gap-3 sm:gap-4 grid-cols-1 lg:grid-cols-2">
          {CATEGORIES.map((cat) => renderResetCard(cat))}
        </div>
      </div>

      {/* Danger Zone — ریست کامل */}
      <div className="mt-6 sm:mt-8">
        <div className="bg-rose-50 dark:bg-rose-500/10 border-2 border-rose-300 dark:border-rose-500/40 rounded-3xl p-4 sm:p-5">
          <div className="flex items-center gap-3 mb-3">
            <div
              className="w-12 h-12 sm:w-14 sm:h-14 rounded-3xl bg-rose-600 flex items-center justify-center text-2xl sm:text-3xl flex-shrink-0 shadow-brand text-white"
              aria-hidden="true"
            >
              🚨
            </div>
            <div className="min-w-0">
              <h2 className="font-display font-black text-base sm:text-lg text-rose-800 dark:text-rose-200">
                منطقه خطر — ریست کامل
              </h2>
              <p className="text-[11px] sm:text-xs text-rose-700 dark:text-rose-300 mt-0.5 leading-relaxed font-bold break-safe">
                تمام داده‌های runtime حذف می‌شن. فقط ادمین، تنظیمات، استانداردها،
                ضرایب، مواد اولیه و عکس‌های سایت باقی می‌مونن.
              </p>
            </div>
          </div>

          {!showAllConfirm ? (
            <button
              type="button"
              onClick={() => setShowAllConfirm(true)}
              className="w-full min-h-[48px] px-4 py-3 bg-rose-600 hover:bg-rose-700 active:bg-rose-800 text-white rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 shadow-brand touch-target"
            >
              <span aria-hidden="true">🚨</span>
              <span>نمایش گزینه ریست کامل</span>
            </button>
          ) : (
            <div className="animate-slide-down">
              {renderResetCard(
                {
                  key: 'all',
                  icon: '🧹',
                  iconBg: 'bg-rose-100 dark:bg-rose-500/20',
                  iconText: 'text-rose-700 dark:text-rose-300',
                  border: 'border-rose-300 dark:border-rose-500/40',
                  bg: 'bg-rose-50/50 dark:bg-rose-500/10',
                },
                true
              )}
              <button
                type="button"
                onClick={() => setShowAllConfirm(false)}
                className="mt-3 min-h-[40px] px-4 py-2 bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 hover:bg-paper-100 dark:hover:bg-ink-700 text-ink-700 dark:text-cream-200 rounded-2xl text-xs font-black transition touch-target"
              >
                ← پنهان کردن
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Footer note */}
      <div className="bg-paper-100 dark:bg-ink-800/50 border border-ink-200 dark:border-dark-700 rounded-2xl p-3 sm:p-4 text-[11px] sm:text-xs text-ink-600 dark:text-cream-400 leading-relaxed font-bold break-safe">
        <div className="flex items-start gap-2">
          <span className="flex-shrink-0 mt-0.5" aria-hidden="true">💡</span>
          <span>
            پس از ریست، شناسه‌های رکوردها (مثل order_id, user_id) از{' '}
            <strong className="font-num">۱</strong> شروع می‌شن. اگه فقط می‌خوای
            دیتای مالی اشتباه رو پاک کنی، «ریست سفارش‌ها» کافیه. کاربران و سگ‌ها
            باقی می‌مونن و می‌تونن دوباره سفارش بدن.
          </span>
        </div>
      </div>
    </div>
  );
}
