// ✅ FIX: ارقام فارسی
const fmtNum = (n) => {
  if (n === null || n === undefined || n === '') return '—';
  const num = Number(n);
  if (Number.isNaN(num)) return '—';
  if (num % 1 === 0) return toFaRaw(num);
  return toFaDecimal(num, 2);
};

const getValueStyle = (value) => {
  const v = Number(value);
  if (v > 1.001) {
    return {
      bg: 'bg-brand-50 dark:bg-brand-500/15',
      text: 'text-brand-700 dark:text-brand-300',
      border: 'border-brand-200 dark:border-brand-500/30',
      arrow: '↑',
      title: 'افزایش نسبت به حالت پایه',
    };
  }
  if (v < 0.999) {
    return {
      bg: 'bg-rose-50 dark:bg-rose-500/15',
      text: 'text-rose-700 dark:text-rose-300',
      border: 'border-rose-200 dark:border-rose-500/30',
      arrow: '↓',
      title: 'کاهش نسبت به حالت پایه',
    };
  }
  return {
    bg: 'bg-ink-100 dark:bg-ink-700',
    text: 'text-ink-500 dark:text-cream-400',
    border: 'border-ink-200 dark:border-dark-600',
    arrow: '·',
    title: 'بدون تغییر',
  };
};

// ============================================================
//  FactorCard — Mobile Editorial
// ============================================================
function FactorCard({
  item,
  isChanged,
  isMobile,
  editingCell,
  editingValue,
  setEditingValue,
  cellInputRef,
  onStartEdit,
  onSaveEdit,
  onCancelEdit,
  onCellKeyDown,
  onEdit,
  onReset,
  saving,
}) {
  return (
    <div
      className={`bg-paper-50 dark:bg-ink-800 border rounded-3xl shadow-soft overflow-hidden transition-all ${
        isChanged
          ? 'border-brand-200 dark:border-brand-500/30'
          : 'border-ink-200 dark:border-dark-700'
      }`}
    >
      <div
        className={`p-3.5 flex items-center justify-between gap-3 border-b ${
          isChanged
            ? 'bg-brand-50/50 dark:bg-brand-500/10 border-brand-200 dark:border-brand-500/20'
            : 'bg-paper-100/50 dark:bg-ink-900/20 border-ink-200 dark:border-dark-700'
        }`}
      >
        <div className="flex items-center gap-2 min-w-0 flex-1">
          {isChanged && (
            <span
              className="w-2 h-2 rounded-full bg-brand-500 animate-pulse flex-shrink-0"
              title="از پیش‌فرض تغییر کرده"
              aria-hidden="true"
            />
          )}
          <div className="min-w-0 flex-1">
            <div
              className="font-display font-black text-ink-800 dark:text-cream-100 text-sm truncate"
              dir={/^[A-Za-z]/.test(item.key) ? 'ltr' : 'rtl'}
            >
              {item.key}
            </div>
            <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-0.5 truncate font-bold">
              {KEY_LABELS[item.key] || '—'}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-1.5 flex-shrink-0">
          <button
            type="button"
            onClick={() => onEdit(item)}
            disabled={saving}
            className="w-10 h-10 min-h-[40px] flex items-center justify-center bg-brand-50 dark:bg-brand-500/15 hover:bg-brand-100 dark:hover:bg-brand-500/25 active:bg-brand-200 text-brand-600 dark:text-brand-300 border border-brand-200 dark:border-brand-500/30 rounded-2xl transition text-sm touch-target disabled:opacity-50"
            title="ویرایش کامل"
            aria-label="ویرایش"
          >
            ✏️
          </button>
          {isChanged && (
            <button
              type="button"
              onClick={() => onReset(item)}
              disabled={saving}
              className="w-10 h-10 min-h-[40px] flex items-center justify-center bg-brand-100 dark:bg-brand-500/25 hover:bg-brand-200 dark:hover:bg-brand-500/35 active:bg-brand-300 text-brand-700 dark:text-brand-200 border border-brand-300 dark:border-brand-500/40 rounded-2xl transition text-sm touch-target disabled:opacity-50"
              title="بازگشت به پیش‌فرض"
              aria-label="بازگشت"
            >
              ↺
            </button>
          )}
        </div>
      </div>

      <div className="p-3 grid grid-cols-2 gap-2">
        {MULTIPLIER_COLUMNS.map((col) => {
          const value = item[col.key];
          const style = getValueStyle(value);
          const isEditing =
            editingCell?.factorId === item.id && editingCell?.field === col.key;

          return (
            <div
              key={col.key}
              onClick={() =>
                !saving && !isEditing && onStartEdit(item, col.key)
              }
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (
                  (e.key === 'Enter' || e.key === ' ') &&
                  !saving &&
                  !isEditing
                ) {
                  e.preventDefault();
                  onStartEdit(item, col.key);
                }
              }}
              className={`cursor-pointer select-none transition rounded-2xl border-2 p-2 min-h-[64px] flex flex-col items-center justify-center touch-target ${
                isEditing
                  ? 'bg-brand-100 dark:bg-brand-500/25 border-brand-400 dark:border-brand-500/50'
                  : `${style.bg} ${style.border} active:scale-[0.97]`
              }`}
              title={isEditing ? '' : 'کلیک برای ویرایش'}
            >
              <div className="text-[9px] text-ink-500 dark:text-cream-400 mb-1 flex items-center gap-1 font-black">
                <span aria-hidden="true">{col.icon}</span>
                <span className="truncate">{col.label}</span>
              </div>

              {isEditing ? (
                <input
                  ref={cellInputRef}
                  type="number"
                  step="0.01"
                  min="0"
                  value={editingValue}
                  onChange={(e) => setEditingValue(e.target.value)}
                  onKeyDown={(e) => onCellKeyDown(e, item)}
                  onBlur={() => onSaveEdit(item)}
                  onClick={(e) => e.stopPropagation()}
                  disabled={saving}
                  className="w-full p-1.5 border-2 border-brand-500 rounded-xl text-center outline-none text-sm font-black font-num bg-paper-50 dark:bg-ink-800 text-ink-900 dark:text-cream-100 tabular-nums"
                  dir="ltr"
                />
              ) : (
                <div className={`flex items-center gap-1 ${style.text}`}>
                  <span className="text-[10px] opacity-60" aria-hidden="true">
                    {style.arrow}
                  </span>
                  {/* ✅ FIX: font-num */}
                  <span className="font-num font-black text-sm tabular-nums">
                    {fmtNum(value)}
                  </span>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function FactorsManager() {
  const { toast, showToast, hideToast } = useToast();

  const [view, setView] = useState('factors');

  // ✅ FIX: همگام با AdminApp — BP = 1280 (نه 1024)
  // این باعث میشه در محدوده 1024-1280px (تبلت/لپ‌تاپ کوچک)
  // که سایدبار compact (w-16) میشه، گرید به‌جای جدول نمایش داده بشه
  // و محتوا فشرده نشه.
  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined'
      ? window.innerWidth < MOBILE_BREAKPOINT
      : false
  );

  useEffect(() => {
    const check = () =>
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  const [factors, setFactors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [openCategories, setOpenCategories] = useState({ 'سنی': true });

  const [searchInput, setSearchInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showOnlyChanged, setShowOnlyChanged] = useState(false);

  const [editingCell, setEditingCell] = useState(null);
  const [editingValue, setEditingValue] = useState('');
  const cellInputRef = useRef(null);

  const [showModal, setShowModal] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({
    energy_mult: '',
    protein_mult: '',
    fat_mult: '',
    carb_mult: '',
    fiber_mult: '',
    calcium_mult: '',
    phosphorus_mult: '',
    description: '',
  });

  const isMountedRef = useRef(true);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  // ============================================================
  //  Fetch
  // ============================================================
  const fetchFactors = async () => {
    setLoading(true);
    try {
      const res = await axios.get('/admin/adjustment-factors');
      if (!isMountedRef.current) return;
      setFactors(res.data || []);
    } catch (err) {
      if (!isMountedRef.current) return;
      showToast('error', getErrorMsg(err, 'خطا در دریافت لیست ضرایب'));
    } finally {
      if (isMountedRef.current) setLoading(false);
    }
  };

  useEffect(() => {
    fetchFactors();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const t = setTimeout(() => setSearchTerm(searchInput), 300);
    return () => clearTimeout(t);
  }, [searchInput]);

  useEffect(() => {
    if (editingCell && cellInputRef.current) {
      cellInputRef.current.focus();
      cellInputRef.current.select();
    }
  }, [editingCell]);

  // ============================================================
  //  Group
  // ============================================================
  const grouped = useMemo(() => {
    const acc = {};
    factors.forEach((f) => {
      if (!acc[f.category]) acc[f.category] = [];
      acc[f.category].push(f);
    });
    return acc;
  }, [factors]);

  const isChanged = (item) => {
    const def = DEFAULT_FACTORS[item.category]?.[item.key];
    if (!def) return false;
    return MULTIPLIER_COLUMNS.some((col) => {
      const a = Number(item[col.key]);
      const b = Number(def[col.key]);
      return Math.abs(a - b) > 0.001;
    });
  };

  const changedCount = useMemo(
    () => factors.filter(isChanged).length,
    [factors]
  );

  // ============================================================
  //  Filter
  // ============================================================
  const filteredGrouped = useMemo(() => {
    const q = searchTerm.trim().toLowerCase();
    const acc = {};
    CATEGORY_ORDER.forEach((cat) => {
      const items = (grouped[cat] || []).filter((item) => {
        if (showOnlyChanged && !isChanged(item)) return false;
        if (!q) return true;
        const hay = [
          item.key,
          item.description,
          KEY_LABELS[item.key] || '',
          cat,
        ]
          .join(' ')
          .toLowerCase();
        return hay.includes(q);
      });
      if (items.length > 0) acc[cat] = items;
    });
    return acc;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [grouped, searchTerm, showOnlyChanged]);

  useEffect(() => {
    if (searchTerm.trim()) {
      const allOpen = {};
      Object.keys(filteredGrouped).forEach((c) => {
        allOpen[c] = true;
      });
      setOpenCategories(allOpen);
    }
  }, [searchTerm, filteredGrouped]);

  const toggleCategory = (cat) => {
    setOpenCategories((prev) => ({ ...prev, [cat]: !prev[cat] }));
  };

  const toggleAll = () => {
    const allOpen = Object.keys(filteredGrouped).every(
      (c) => openCategories[c]
    );
    const next = {};
    Object.keys(filteredGrouped).forEach((c) => {
      next[c] = !allOpen;
    });
    setOpenCategories(next);
  };

  // ============================================================
  //  Inline Edit
  // ============================================================
  const startInlineEdit = (item, field) => {
    setEditingCell({ factorId: item.id, field });
    setEditingValue(String(item[field] ?? ''));
  };

  const cancelInlineEdit = () => {
    setEditingCell(null);
    setEditingValue('');
  };

  const saveInlineEdit = async (item) => {
    if (!editingCell) return;
    const value = parseFloat(editingValue);
    if (isNaN(value) || value < 0) {
      showToast('error', 'مقدار باید یک عدد غیر منفی باشد');
      cancelInlineEdit();
      return;
    }
    if (Number(item[editingCell.field]) === value) {
      cancelInlineEdit();
      return;
    }

    setSaving(true);
    try {
      const payload = {
        energy_mult: item.energy_mult,
        protein_mult: item.protein_mult,
        fat_mult: item.fat_mult,
        carb_mult: item.carb_mult,
        fiber_mult: item.fiber_mult,
        calcium_mult: item.calcium_mult,
        phosphorus_mult: item.phosphorus_mult,
        description: item.description || '',
      };
      payload[editingCell.field] = value;

      await axios.put(
        `/admin/adjustment-factors/${item.id}`,
        payload
      );

      if (!isMountedRef.current) return;
      setFactors((prev) =>
        prev.map((f) =>
          f.id === item.id ? { ...f, [editingCell.field]: value } : f
        )
      );
      cancelInlineEdit();
      showToast('success', 'ضریب با موفقیت ذخیره شد');
    } catch (err) {
      if (!isMountedRef.current) return;
      showToast('error', getErrorMsg(err, 'خطا در ذخیره'));
    } finally {
      if (isMountedRef.current) setSaving(false);
    }
  };

  const handleCellKeyDown = (e, item) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      saveInlineEdit(item);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      cancelInlineEdit();
    }
  };

  // ============================================================
  //  Reset
  // ============================================================
  const handleResetRow = async (item) => {
    const def = DEFAULT_FACTORS[item.category]?.[item.key];
    if (!def) {
      showToast('error', 'مقدار پیش‌فرض برای این ردیف یافت نشد');
      return;
    }
    if (!window.confirm(`مقادیر «${item.key}» به پیش‌فرض بازگردد؟`)) return;

    setSaving(true);
    try {
      await axios.put(
        `/admin/adjustment-factors/${item.id}`,
        {
          ...def,
          description: item.description || '',
        }
      );
      if (!isMountedRef.current) return;
      setFactors((prev) =>
        prev.map((f) => (f.id === item.id ? { ...f, ...def } : f))
      );
      showToast('success', `«${item.key}» به پیش‌فرض بازگشت`);
    } catch (err) {
      if (!isMountedRef.current) return;
      showToast('error', getErrorMsg(err, 'خطا در بازگشت به پیش‌فرض'));
    } finally {
      if (isMountedRef.current) setSaving(false);
    }
  };

  const handleResetAll = async () => {
    if (changedCount === 0) {
      showToast('info', 'هیچ ضریبی تغییر نکرده است');
      return;
    }
    // ✅ FIX: toFaRaw در confirm
    if (
      !window.confirm(
        `⚠️ تمام ${toFaRaw(
          changedCount
        )} ضریب تغییرکرده به پیش‌فرض بازگردانده می‌شوند.\n\nآیا مطمئن هستید؟`
      )
    )
      return;

    setSaving(true);
    let successCount = 0;
    let failCount = 0;

    for (const item of factors) {
      if (!isChanged(item)) continue;
      const def = DEFAULT_FACTORS[item.category]?.[item.key];
      if (!def) continue;
      try {
        await axios.put(
          `/admin/adjustment-factors/${item.id}`,
          {
            ...def,
            description: item.description || '',
          }
        );
        successCount++;
      } catch {
        failCount++;
      }
    }

    await fetchFactors();
    if (!isMountedRef.current) return;
    setSaving(false);

    // ✅ FIX: toFaRaw در toast
    if (failCount === 0) {
      showToast(
        'success',
        `${toFaRaw(successCount)} ضریب به پیش‌فرض بازگشت`
      );
    } else {
      showToast(
        'error',
        `${toFaRaw(successCount)} موفق، ${toFaRaw(failCount)} ناموفق`
      );
    }
  };

  // ============================================================
  //  Modal
  // ============================================================
  const openModal = (item) => {
    setEditingItem(item);
    setFormData({
      energy_mult: item.energy_mult ?? '',
      protein_mult: item.protein_mult ?? '',
      fat_mult: item.fat_mult ?? '',
      carb_mult: item.carb_mult ?? '',
      fiber_mult: item.fiber_mult ?? '',
      calcium_mult: item.calcium_mult ?? '',
      phosphorus_mult: item.phosphorus_mult ?? '',
      description: item.description ?? '',
    });
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setEditingItem(null);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmitModal = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const data = {
        energy_mult: parseFloat(formData.energy_mult) || 0,
        protein_mult: parseFloat(formData.protein_mult) || 0,
        fat_mult: parseFloat(formData.fat_mult) || 0,
        carb_mult: parseFloat(formData.carb_mult) || 0,
        fiber_mult: parseFloat(formData.fiber_mult) || 0,
        calcium_mult: parseFloat(formData.calcium_mult) || 0,
        phosphorus_mult: parseFloat(formData.phosphorus_mult) || 0,
        description: formData.description || '',
      };

      await axios.put(
        `/admin/adjustment-factors/${editingItem.id}`,
        data
      );
      if (!isMountedRef.current) return;
      showToast('success', 'ضریب با موفقیت ویرایش شد');
      closeModal();
      fetchFactors();
    } catch (err) {
      if (!isMountedRef.current) return;
      showToast('error', getErrorMsg(err, 'خطا در ویرایش'));
    } finally {
      if (isMountedRef.current) setSaving(false);
    }
  };

  const hasAnyResult = Object.keys(filteredGrouped).length > 0;
  const categoriesWithChanges = CATEGORY_ORDER.filter((c) =>
    (filteredGrouped[c] || []).some(isChanged)
  ).length;

  // ============================================================
  //  رندر
  // ============================================================
  return (
    <div
      className="p-3 sm:p-4 max-w-7xl mx-auto space-y-4 sm:space-y-5"
      dir="rtl"
    >
      {/* Tab Bar */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-1.5 shadow-soft">
        <div className="flex gap-1.5 overflow-x-auto scrollbar-hide">
          <button
            type="button"
            onClick={() => setView('factors')}
            className={`flex-1 min-w-[160px] sm:min-w-[180px] px-3 sm:px-4 py-3 min-h-[48px] rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 whitespace-nowrap touch-target ${
              view === 'factors'
                ? 'bg-brand-gradient text-white shadow-brand'
                : 'text-ink-600 dark:text-cream-300 hover:bg-paper-100 dark:hover:bg-ink-700/50 active:bg-paper-200'
            }`}
          >
            <SiteImage imageKey="icon_ruler" fallback="📐" alt="" className="text-lg" />
            <span>ضرایب اصلاحی</span>
          </button>
          <button
            type="button"
            onClick={() => setView('standards')}
            className={`flex-1 min-w-[160px] sm:min-w-[180px] px-3 sm:px-4 py-3 min-h-[48px] rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 whitespace-nowrap touch-target ${
              view === 'standards'
                ? 'bg-brand-gradient text-white shadow-brand'
                : 'text-ink-600 dark:text-cream-300 hover:bg-paper-100 dark:hover:bg-ink-700/50 active:bg-paper-200'
            }`}
          >
            <SiteImage imageKey="icon_chart" fallback="📊" alt="" className="text-lg" />
            <span>استانداردهای تغذیه</span>
          </button>
        </div>
      </div>

      {view === 'standards' ? (
        <NutritionRequirements />
      ) : (
        <>
          {/* Hero Header */}
          <div className="bg-ink-900 dark:bg-ink-950 text-cream-100 rounded-3xl shadow-editorial relative overflow-hidden noise-overlay">
            <div
              className="absolute -top-16 -left-16 w-48 h-48 bg-brand-500/10 rounded-full"
              aria-hidden="true"
            />
            <div
              className="absolute -bottom-20 -right-20 w-64 h-64 bg-brand-500/5 rounded-full"
              aria-hidden="true"
            />
            <div
              className="absolute top-0 right-1/2 translate-x-1/2 w-20 h-0.5 bg-brand-500"
              aria-hidden="true"
            />

            <div className="relative p-4 sm:p-5 md:p-6">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 sm:gap-4 mb-4 sm:mb-5">
                <div className="flex items-center gap-3 sm:gap-4 min-w-0">
                  <div
                    className="w-12 h-12 sm:w-14 sm:h-14 rounded-3xl bg-brand-gradient flex items-center justify-center text-2xl sm:text-3xl flex-shrink-0 shadow-brand"
                    aria-hidden="true"
                  >
                    📐
                  </div>
                  <div className="min-w-0">
                    <h1 className="font-display font-black text-lg sm:text-xl md:text-2xl tracking-tightest leading-tight">
                      مدیریت ضرایب اصلاحی
                    </h1>
                    <p className="text-[11px] sm:text-xs text-cream-300/80 mt-1 font-bold">
                      {isMobile
                        ? 'کلیک روی عدد برای ویرایش سریع'
                        : 'دابل‌کلیک روی عدد برای ویرایش سریع'}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-2 flex-wrap w-full sm:w-auto">
                  <button
                    type="button"
                    onClick={fetchFactors}
                    className="flex-1 sm:flex-none min-h-[44px] bg-white/10 hover:bg-white/15 backdrop-blur border border-white/15 px-3 sm:px-4 py-2.5 rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 shadow-soft group touch-target"
                    title="بروزرسانی"
                  >
                    <SiteImage imageKey="icon_refresh" fallback="🔄" alt="" className="group-hover:rotate-180 transition-transform duration-500" />
                    <span>بروزرسانی</span>
                  </button>
                  {changedCount > 0 && (
                    <button
                      type="button"
                      onClick={handleResetAll}
                      disabled={saving}
                      className="flex-1 sm:flex-none min-h-[44px] bg-brand-500/90 hover:bg-brand-500 backdrop-blur border border-brand-400/50 px-3 sm:px-4 py-2.5 rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 shadow-soft disabled:opacity-50 touch-target"
                      title="بازگشت همه تغییرات"
                    >
                      <span aria-hidden="true">↺</span>
                      <span>بازگشت ({fmtNum(changedCount)})</span>
                    </button>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                <div className="bg-white/8 backdrop-blur rounded-2xl px-3 py-2.5 text-center border border-white/10">
                  <div className="text-[10px] text-cream-300 mb-0.5 font-black">
                    📂 دسته‌ها
                  </div>
                  <div className="font-display font-black text-sm sm:text-lg font-num tabular-nums">
                    {fmtNum(Object.keys(grouped).length)}
                  </div>
                </div>
                <div className="bg-white/8 backdrop-blur rounded-2xl px-3 py-2.5 text-center border border-white/10">
                  <div className="text-[10px] text-cream-300 mb-0.5 font-black">
                    🔑 کلیدها
                  </div>
                  <div className="font-display font-black text-sm sm:text-lg font-num tabular-nums">
                    {fmtNum(factors.length)}
                  </div>
                </div>
                <div className="bg-white/8 backdrop-blur rounded-2xl px-3 py-2.5 text-center border border-white/10">
                  <div className="text-[10px] text-cream-300 mb-0.5 font-black">
                    ⚠️ تغییرکرده
                  </div>
                  <div
                    className={`font-display font-black text-sm sm:text-lg font-num tabular-nums ${
                      changedCount > 0 ? 'text-brand-300' : ''
                    }`}
                  >
                    {fmtNum(changedCount)}
                  </div>
                </div>
                <div className="bg-white/8 backdrop-blur rounded-2xl px-3 py-2.5 text-center border border-white/10">
                  <div className="text-[10px] text-cream-300 mb-0.5 font-black">
                    📊 دسته تغییر
                  </div>
                  <div className="font-display font-black text-sm sm:text-lg font-num tabular-nums">
                    {fmtNum(categoriesWithChanges)}
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Filters + Legend */}
          <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
            <div className="p-3 sm:p-4 flex flex-col sm:flex-row sm:items-center gap-2 border-b border-ink-200 dark:border-dark-700">
              <div className="relative flex-1 min-w-0">
                <input
                  type="text"
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  placeholder="🔍 جستجو در کلید، توضیح یا دسته..."
                  className="w-full px-4 py-3 pr-11 pl-12 min-h-[48px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition"
                />
                <SiteImage imageKey="icon_search" fallback="🔍" alt="" className="absolute right-3 top-1/2 -translate-y-1/2 text-ink-400 dark:text-cream-500 pointer-events-none" />
                {searchInput && (
                  <button
                    type="button"
                    onClick={() => setSearchInput('')}
                    className="absolute left-1.5 top-1/2 -translate-y-1/2 w-9 h-9 flex items-center justify-center text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 rounded-2xl transition touch-target"
                    title="پاک کردن"
                    aria-label="پاک کردن جستجو"
                  >
                    ✕
                  </button>
                )}
              </div>

              <div className="flex items-center gap-2 flex-wrap">
                <label
                  className={`flex items-center gap-2 px-3 py-2.5 min-h-[48px] border-2 rounded-2xl text-xs cursor-pointer transition touch-target font-black ${
                    showOnlyChanged
                      ? 'bg-brand-50 dark:bg-brand-500/15 border-brand-300 dark:border-brand-500/40 text-brand-800 dark:text-brand-200'
                      : 'bg-paper-100 dark:bg-ink-700/50 border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200 hover:bg-paper-200 dark:hover:bg-ink-700'
                  }`}
                >
                  <input
                    type="checkbox"
                    checked={showOnlyChanged}
                    onChange={(e) => setShowOnlyChanged(e.target.checked)}
                    className="w-5 h-5 cursor-pointer accent-brand-500"
                  />
                  <span className="whitespace-nowrap">فقط تغییرکرده</span>
                </label>

                <button
                  type="button"
                  onClick={toggleAll}
                  className="min-h-[48px] px-3 py-2.5 bg-paper-100 dark:bg-ink-700/50 border border-ink-200 dark:border-dark-600 rounded-2xl text-xs font-black text-ink-700 dark:text-cream-200 hover:bg-paper-200 dark:hover:bg-ink-700 transition flex items-center gap-1.5 touch-target"
                >
                  {Object.keys(filteredGrouped).every(
                    (c) => openCategories[c]
                  ) ? (
                    <>
                      <SiteImage imageKey="icon_arrow_up" fallback="🔼" alt="" className="leading-none inline-flex" />
                      <span>بستن همه</span>
                    </>
                  ) : (
                    <>
                      <SiteImage imageKey="icon_arrow_down" fallback="🔽" alt="" className="leading-none inline-flex" />
                      <span>باز کردن همه</span>
                    </>
                  )}
                </button>
              </div>
            </div>

            <div className="px-3 sm:px-4 py-3 bg-paper-100/50 dark:bg-ink-900/20 flex flex-wrap items-center gap-x-3 gap-y-2 text-[10px] font-black">
              <span className="text-ink-600 dark:text-cream-300">راهنما:</span>
              <span className="flex items-center gap-1 text-ink-500 dark:text-cream-400">
                <span className="w-3 h-3 rounded bg-brand-100 dark:bg-brand-500/25 border border-brand-300 dark:border-brand-500/40" />
                <span>&gt; ۱ (افزایش نیاز)</span>
              </span>
              <span className="flex items-center gap-1 text-ink-500 dark:text-cream-400">
                <span className="w-3 h-3 rounded bg-ink-100 dark:bg-ink-700 border border-ink-300 dark:border-dark-600" />
                <span>= ۱ (بدون تغییر)</span>
              </span>
              <span className="flex items-center gap-1 text-ink-500 dark:text-cream-400">
                <span className="w-3 h-3 rounded bg-rose-100 dark:bg-rose-500/25 border border-rose-300 dark:border-rose-500/40" />
                <span>&lt; ۱ (کاهش نیاز)</span>
              </span>
            </div>
          </div>

          {/* Categories */}
          {loading ? (
            <div className="bg-paper-50 dark:bg-ink-800 rounded-3xl border border-ink-200 dark:border-dark-700 shadow-soft p-12 text-center">
              <div className="inline-block w-10 h-10 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-3" />
              <div className="text-ink-500 dark:text-cream-400 text-sm font-black">
                در حال بارگذاری ضرایب...
              </div>
            </div>
          ) : !hasAnyResult ? (
            <div className="bg-paper-50 dark:bg-ink-800 rounded-3xl border border-ink-200 dark:border-dark-700 shadow-soft p-8 sm:p-12 text-center">
              <div className="text-5xl mb-3 opacity-60" aria-hidden="true">
                📭
              </div>
              <div className="font-display font-black text-ink-700 dark:text-cream-200 mb-1">
                {searchTerm || showOnlyChanged
                  ? 'نتیجه‌ای با این فیلترها یافت نشد'
                  : 'هیچ ضریبی ثبت نشده'}
              </div>
              {(searchTerm || showOnlyChanged) && (
                <button
                  type="button"
                  onClick={() => {
                    setSearchInput('');
                    setShowOnlyChanged(false);
                  }}
                  className="mt-4 w-full sm:w-auto min-h-[48px] px-5 py-2.5 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white rounded-2xl text-xs font-black transition shadow-brand touch-target"
                >
                  ✕ پاک کردن فیلترها
                </button>
              )}
            </div>
          ) : (
            <div className="space-y-3">
              {CATEGORY_ORDER.map((category) => {
                const items = filteredGrouped[category];
                if (!items || items.length === 0) return null;

                const meta = CATEGORY_META[category] || {
                  icon: '📦', iconKey: 'icon_orders',
                  gradient: 'bg-ink-700',
                  desc: '',
                  bg: '',
                  border: '',
                  text: '',
                };
                const isOpen = openCategories[category] === true;
                const catChangedCount = items.filter(isChanged).length;

                return (
                  <div
                    key={category}
                    className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden"
                  >
                    <button
                      type="button"
                      onClick={() => toggleCategory(category)}
                      className="w-full flex items-center justify-between p-4 min-h-[72px] hover:bg-paper-100/60 dark:hover:bg-ink-700/40 active:bg-paper-200 dark:active:bg-ink-700/60 transition text-right touch-target"
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <div
                          className={`w-11 h-11 rounded-2xl ${meta.gradient} flex items-center justify-center text-2xl flex-shrink-0 shadow-brand text-white`}
                        >
                          {meta.icon}
                        </div>
                        <div className="text-right min-w-0">
                          <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm flex items-center gap-2 flex-wrap">
                            <span>{category}</span>
                            <span className="text-[10px] bg-paper-100 dark:bg-ink-700 text-ink-600 dark:text-cream-300 px-2 py-0.5 rounded-full font-black border border-ink-200 dark:border-dark-600 font-num tabular-nums">
                              {fmtNum(items.length)} کلید
                            </span>
                            {catChangedCount > 0 && (
                              <span className="text-[10px] bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 px-2 py-0.5 rounded-full font-black border border-brand-200 dark:border-brand-500/30 flex items-center gap-1">
                                <span
                                  className="w-1.5 h-1.5 rounded-full bg-brand-500 animate-pulse"
                                  aria-hidden="true"
                                />
                                <span className="font-num tabular-nums">
                                  {fmtNum(catChangedCount)} تغییر
                                </span>
                              </span>
                            )}
                          </div>
                          <div className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 truncate font-bold">
                            {meta.desc}
                          </div>
                        </div>
                      </div>
                      <SiteImage imageKey="icon_chevron_left" fallback="◀" alt="" className="leading-none inline-flex" />
                    </button>

                    {isOpen && (
                      <>
                        {/* دسکتاپ */}
                        {/* ✅ FIX: استفاده از !isMobile به جای lg:block — هماهنگ با BP=1280 */}
                        <div className={`${isMobile ? 'hidden' : 'block'} border-t border-ink-200 dark:border-dark-700 overflow-x-auto`}>
                          <table className="w-full text-sm">
                            <thead className="bg-ink-900 dark:bg-ink-950 text-cream-100">
                              <tr>
                                <th className="p-3 text-right font-black text-[11px] whitespace-nowrap">
                                  کلید
                                </th>
                                {MULTIPLIER_COLUMNS.map((col) => (
                                  <th
                                    key={col.key}
                                    className="p-3 text-center font-black text-[11px] whitespace-nowrap cursor-help"
                                    title={col.hint}
                                  >
                                    <div className="flex items-center justify-center gap-1">
                                      <span aria-hidden="true">
                                        {col.icon}
                                      </span>
                                      <span>{col.label}</span>
                                    </div>
                                  </th>
                                ))}
                                <th className="p-3 text-center font-black text-[11px] whitespace-nowrap">
                                  عملیات
                                </th>
                              </tr>
                            </thead>

                            <tbody className="divide-y divide-ink-200 dark:divide-dark-700">
                              {items.map((item) => {
                                const changed = isChanged(item);
                                return (
                                  <tr
                                    key={item.id}
                                    className={`transition ${
                                      changed
                                        ? 'bg-brand-50/40 dark:bg-brand-500/10'
                                        : 'hover:bg-paper-100/60 dark:hover:bg-ink-700/40'
                                    }`}
                                  >
                                    <td className="p-3">
                                      <div className="flex items-center gap-2 min-w-0">
                                        {changed && (
                                          <span
                                            className="w-2 h-2 rounded-full bg-brand-500 animate-pulse flex-shrink-0"
                                            title="از پیش‌فرض تغییر کرده"
                                            aria-hidden="true"
                                          />
                                        )}
                                        <div className="min-w-0">
                                          <div
                                            className="font-display font-black text-ink-800 dark:text-cream-100 text-xs"
                                            dir={
                                              /^[A-Za-z]/.test(item.key)
                                                ? 'ltr'
                                                : 'rtl'
                                            }
                                          >
                                            {item.key}
                                          </div>
                                          <div className="text-[10px] text-ink-400 dark:text-cream-500 mt-0.5 font-bold">
                                            {KEY_LABELS[item.key] || '—'}
                                          </div>
                                        </div>
                                      </div>
                                    </td>

                                    {MULTIPLIER_COLUMNS.map((col) => {
                                      const value = item[col.key];
                                      const style = getValueStyle(value);
                                      const isEditing =
                                        editingCell?.factorId === item.id &&
                                        editingCell?.field === col.key;

                                      return (
                                        <td
                                          key={col.key}
                                          className={`p-2 text-center cursor-pointer select-none transition rounded-xl ${
                                            isEditing
                                              ? 'bg-brand-100 dark:bg-brand-500/25'
                                              : 'hover:bg-brand-50 dark:hover:bg-brand-500/15'
                                          }`}
                                          onDoubleClick={() =>
                                            !saving &&
                                            !isEditing &&
                                            startInlineEdit(item, col.key)
                                          }
                                          title={
                                            isEditing
                                              ? ''
                                              : 'دابل‌کلیک برای ویرایش'
                                          }
                                        >
                                          {isEditing ? (
                                            <input
                                              ref={cellInputRef}
                                              type="number"
                                              step="0.01"
                                              min="0"
                                              value={editingValue}
                                              onChange={(e) =>
                                                setEditingValue(
                                                  e.target.value
                                                )
                                              }
                                              onKeyDown={(e) =>
                                                handleCellKeyDown(e, item)
                                              }
                                              onBlur={() =>
                                                saveInlineEdit(item)
                                              }
                                              disabled={saving}
                                              className="w-20 p-1.5 border-2 border-brand-500 rounded-xl text-center outline-none text-xs font-black font-num bg-paper-50 dark:bg-ink-800 text-ink-900 dark:text-cream-100 tabular-nums"
                                              dir="ltr"
                                            />
                                          ) : (
                                            <div
                                              className={`inline-flex items-center gap-1 px-2 py-1 rounded-xl border text-xs font-black ${style.bg} ${style.text} ${style.border}`}
                                              title={style.title}
                                            >
                                              <span
                                                className="text-[9px] opacity-60"
                                                aria-hidden="true"
                                              >
                                                {style.arrow}
                                              </span>
                                              <span className="font-num tabular-nums">
                                                {fmtNum(value)}
                                              </span>
                                            </div>
                                          )}
                                        </td>
                                      );
                                    })}

                                    <td className="p-2">
                                      <div className="flex items-center justify-center gap-1.5">
                                        <button
                                          type="button"
                                          onClick={() => openModal(item)}
                                          disabled={saving}
                                          className="w-9 h-9 flex items-center justify-center bg-brand-50 dark:bg-brand-500/15 hover:bg-brand-100 dark:hover:bg-brand-500/25 text-brand-600 dark:text-brand-300 border border-brand-200 dark:border-brand-500/30 rounded-xl transition text-xs hover:-translate-y-0.5 disabled:opacity-50 touch-target"
                                          title="ویرایش کامل"
                                        >
                                          ✏️
                                        </button>
                                        {changed && (
                                          <button
                                            type="button"
                                            onClick={() =>
                                              handleResetRow(item)
                                            }
                                            disabled={saving}
                                            className="w-9 h-9 flex items-center justify-center bg-brand-100 dark:bg-brand-500/25 hover:bg-brand-200 dark:hover:bg-brand-500/35 text-brand-700 dark:text-brand-200 border border-brand-300 dark:border-brand-500/40 rounded-xl transition text-xs hover:-translate-y-0.5 disabled:opacity-50 touch-target"
                                            title="بازگشت به پیش‌فرض"
                                          >
                                            ↺
                                          </button>
                                        )}
                                      </div>
                                    </td>
                                  </tr>
                                );
                              })}
                            </tbody>
                          </table>
                        </div>

                        {/* موبایل */}
                        {/* ✅ FIX: استفاده از isMobile به جای lg:hidden — هماهنگ با BP=1280 */}
                        <div className={`${isMobile ? 'block' : 'hidden'} p-3 space-y-3 bg-paper-100/50 dark:bg-ink-900/20`}>
                          {items.map((item) => (
                            <FactorCard
                              key={item.id}
                              item={item}
                              isChanged={isChanged(item)}
                              isMobile={isMobile}
                              editingCell={editingCell}
                              editingValue={editingValue}
                              setEditingValue={setEditingValue}
                              cellInputRef={cellInputRef}
                              onStartEdit={startInlineEdit}
                              onSaveEdit={saveInlineEdit}
                              onCancelEdit={cancelInlineEdit}
                              onCellKeyDown={handleCellKeyDown}
                              onEdit={openModal}
                              onReset={handleResetRow}
                              saving={saving}
                            />
                          ))}
                        </div>
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </>
      )}

      {/* Edit Modal */}
      {showModal && editingItem && (
        <div
          className="fixed inset-0 bg-ink-900/70 backdrop-blur-sm flex items-end sm:items-center justify-center z-50 p-0 sm:p-4 no-print"
          role="dialog"
          aria-modal="true"
          aria-label="ویرایش ضریب"
        >
          <div className="bg-paper-50 dark:bg-ink-800 rounded-t-3xl sm:rounded-3xl shadow-editorial w-full sm:max-w-2xl max-h-[92vh] sm:max-h-[90vh] flex flex-col overflow-hidden safe-bottom border border-ink-200 dark:border-dark-700">
            <div className="sm:hidden w-12 h-1.5 bg-ink-300 dark:bg-dark-600 rounded-full mx-auto mt-2 flex-shrink-0" />

            <div className="p-4 sm:p-5 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-brand-50/50 dark:bg-brand-500/10 flex-shrink-0">
              <div
                className="w-10 h-10 sm:w-11 sm:h-11 rounded-2xl bg-brand-100 dark:bg-brand-500/20 flex items-center justify-center text-lg sm:text-xl text-brand-700 dark:text-brand-300 flex-shrink-0"
                aria-hidden="true"
              >
                ✏️
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-display font-black text-ink-800 dark:text-cream-100 text-sm truncate">
                  ویرایش: {editingItem.key}
                </h3>
                <p className="text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 truncate font-bold">
                  {editingItem.category} — {KEY_LABELS[editingItem.key] || ''}
                </p>
              </div>
              <button
                type="button"
                onClick={closeModal}
                className="w-10 h-10 flex items-center justify-center text-ink-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 rounded-2xl transition text-lg flex-shrink-0 touch-target"
                aria-label="بستن"
              >
                ✕
              </button>
            </div>

            <form
              onSubmit={handleSubmitModal}
              className="flex-1 overflow-y-auto"
            >
              <div className="p-4 sm:p-5 space-y-4">
                <div className="bg-paper-100 dark:bg-ink-900/40 rounded-2xl p-3 sm:p-4 border border-ink-200 dark:border-dark-700">
                  <h4 className="text-xs font-black text-ink-800 dark:text-cream-200 mb-3 flex items-center gap-2">
                    <SiteImage imageKey="icon_chart" fallback="📊" alt="" className="w-6 h-6 rounded-2xl bg-brand-100 dark:bg-brand-500/20 text-brand-700 dark:text-brand-300 flex items-center justify-center text-[10px] font-black flex-shrink-0" />
                    <span>مقادیر ضریب</span>
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                    {MULTIPLIER_COLUMNS.map((col) => (
                      <div key={col.key}>
                        <label className="flex items-center gap-1.5 text-[11px] font-black text-ink-600 dark:text-cream-300 mb-1.5">
                          <span aria-hidden="true">{col.icon}</span>
                          <span>{col.label}</span>
                        </label>
                        <input
                          name={col.key}
                          type="number"
                          step="0.01"
                          value={formData[col.key]}
                          onChange={handleChange}
                          required
                          className="w-full px-3 py-3 min-h-[48px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition font-num tabular-nums"
                          dir="ltr"
                        />
                        <div className="text-[9px] text-ink-400 dark:text-cream-500 mt-0.5 leading-relaxed font-bold">
                          {col.hint}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="bg-paper-100 dark:bg-ink-900/40 rounded-2xl p-3 sm:p-4 border border-ink-200 dark:border-dark-700">
                  <label className="flex items-center gap-1.5 text-xs font-black text-ink-800 dark:text-cream-200 mb-2">
                    <SiteImage imageKey="icon_note" fallback="📝" alt="" className="leading-none inline-flex" />
                    <span>توضیحات</span>
                  </label>
                  <input
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    placeholder="توضیح کوتاه (اختیاری)"
                    className="w-full px-3 py-3 min-h-[48px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition"
                  />
                </div>

                {isChanged(editingItem) && (
                  <div className="bg-brand-50 dark:bg-brand-500/15 border-2 border-brand-200 dark:border-brand-500/30 rounded-2xl p-3 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                    <div className="flex items-center gap-2 text-xs text-brand-800 dark:text-brand-200 font-black">
                      <span
                        className="w-2 h-2 rounded-full bg-brand-500 animate-pulse flex-shrink-0"
                        aria-hidden="true"
                      />
                      <span>این ضریب از پیش‌فرض تغییر کرده است</span>
                    </div>
                    <button
                      type="button"
                      onClick={() => {
                        const def =
                          DEFAULT_FACTORS[editingItem.category]?.[
                            editingItem.key
                          ];
                        if (def) {
                          setFormData({
                            ...def,
                            description: formData.description,
                          });
                        }
                      }}
                      className="w-full sm:w-auto min-h-[40px] px-3 py-1.5 bg-paper-50 dark:bg-ink-700 border border-brand-300 dark:border-brand-500/40 text-brand-700 dark:text-brand-300 rounded-2xl text-xs font-black hover:bg-brand-100 dark:hover:bg-brand-500/25 transition flex items-center justify-center gap-1 touch-target"
                    >
                      <span aria-hidden="true">↺</span>
                      <span>پر کردن با پیش‌فرض</span>
                    </button>
                  </div>
                )}
              </div>

              <div className="p-3 sm:p-4 border-t border-ink-200 dark:border-dark-700 bg-paper-100/50 dark:bg-ink-900/30 flex flex-col-reverse sm:flex-row sm:justify-end gap-2 flex-shrink-0 sticky bottom-0">
                <button
                  type="button"
                  onClick={closeModal}
                  disabled={saving}
                  className="w-full sm:w-auto min-h-[48px] px-4 py-2.5 bg-paper-50 dark:bg-ink-700 border border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200 rounded-2xl text-sm font-black hover:bg-paper-100 dark:hover:bg-ink-600 active:bg-paper-200 transition touch-target disabled:opacity-50"
                >
                  انصراف
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  className={`w-full sm:w-auto min-h-[48px] px-6 py-2.5 rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 shadow-brand touch-target ${
                    saving
                      ? 'bg-paper-200 dark:bg-ink-700 text-ink-400 cursor-wait'
                      : 'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white hover:shadow-brand-lg'
                  }`}
                >
                  {saving ? (
                    <>
                      <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      <span>در حال ذخیره...</span>
                    </>
                  ) : (
                    <>
                      <SiteImage imageKey="icon_save" fallback="💾" alt="" className="leading-none inline-flex" />
                      <span>ذخیره</span>
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ✅ FIX: Toast استاندارد با useToast */}
      {toast && <ToastView {...toast} onClose={hideToast} />}
    </div>
  );
}
