const fmt = (n) => Math.round(n || 0).toLocaleString('fa-IR');

const fmtDec = (n, dec = 1) =>
  Number(n || 0).toLocaleString('fa-IR', {
    minimumFractionDigits: 0,
    maximumFractionDigits: dec,
  });

const fmtShort = (n) => {
  const num = Math.round(n || 0);
  if (num >= 1_000_000_000) return `${fmtDec(num / 1_000_000_000, 1)} میلیارد`;
  if (num >= 1_000_000) return `${fmtDec(num / 1_000_000, 1)} میلیون`;
  if (num >= 1_000) return `${fmtDec(num / 1_000, 0)} هزار`;
  return num.toLocaleString('fa-IR');
};

const formatDate = (iso) => {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '—';
  return d.toLocaleDateString('fa-IR');
};

