// ============================================================
//  ChangeBadge — Editorial
// ============================================================
function ChangeBadge({ value, invertColor = false, light = false }) {
  if (value === undefined || value === null || value === 0) return null;

  const isPositive = value > 0;
  const isGood = invertColor ? !isPositive : isPositive;

  const cls = light
    ? isGood
      ? 'bg-accent-400/30 text-accent-100'
      : 'bg-rose-400/30 text-rose-100'
    : isGood
    ? 'bg-accent-50 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300 border border-accent-200 dark:border-accent-500/30'
    : 'bg-rose-50 dark:bg-rose-500/20 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-500/30';

  return (
    <span
      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black font-num ${cls}`}
    >
      <span aria-hidden="true">{isPositive ? '▲' : '▼'}</span>
      <span className="tabular-nums">
        {fmtDec(Math.abs(value), 1)}٪
      </span>
    </span>
  );
}

