// ============================================================
//  CostBar — Editorial
// ============================================================
function CostBar({ material, overhead, profit, total }) {
  if (!total || total <= 0) {
    return (
      <div className="text-center text-sm text-ink-400 dark:text-cream-500 py-6">
        <div className="text-4xl mb-2 opacity-50" aria-hidden="true">📊</div>
        <div className="text-xs font-bold">داده‌ای برای نمایش نیست</div>
      </div>
    );
  }

  const materialPct = (material / total) * 100;
  const overheadPct = (overhead / total) * 100;
  const profitPct = (profit / total) * 100;

  const items = [
    { label: 'مواد اولیه', pct: materialPct, value: material, color: 'bg-brand-500', bgLight: 'bg-brand-50 dark:bg-brand-500/15', text: 'text-brand-700 dark:text-brand-300', icon: '🥩', iconKey: 'allergen_beef' },
    { label: 'سربار', pct: overheadPct, value: overhead, color: 'bg-brand-700', bgLight: 'bg-brand-100 dark:bg-brand-500/20', text: 'text-brand-800 dark:text-brand-200', icon: '🏭', iconKey: 'icon_factory' },
    { label: 'سود خالص', pct: profitPct, value: profit, color: 'bg-accent-500', bgLight: 'bg-accent-50 dark:bg-accent-500/15', text: 'text-accent-700 dark:text-accent-300', icon: '💎', iconKey: 'icon_gem' },
  ];

  return (
    <div className="space-y-3 sm:space-y-4">
      <div className="flex h-3 sm:h-3.5 rounded-full overflow-hidden bg-paper-100 dark:bg-ink-700">
        <div className="bg-brand-500 transition-all duration-700" style={{ width: `${materialPct}%` }} title={`مواد: ${materialPct.toFixed(1)}%`} />
        <div className="bg-brand-700 transition-all duration-700" style={{ width: `${overheadPct}%` }} title={`سربار: ${overheadPct.toFixed(1)}%`} />
        <div className="bg-accent-500 transition-all duration-700" style={{ width: `${profitPct}%` }} title={`سود: ${profitPct.toFixed(1)}%`} />
      </div>

      <div className="space-y-2">
        {items.map((item, i) => (
          <div key={i} className="flex items-center gap-2 sm:gap-3">
            <div className={`w-8 h-8 sm:w-9 sm:h-9 rounded-2xl flex items-center justify-center text-sm sm:text-base flex-shrink-0 ${item.bgLight}`}>
              {item.icon}
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between text-[10px] sm:text-[11px] mb-1 gap-2">
                <span className={`font-black ${item.text} truncate`}>{item.label}</span>
                <span className="text-ink-500 dark:text-cream-400 font-num tabular-nums whitespace-nowrap">
                  {fmt(item.value)} ت
                </span>
              </div>
              <div className="w-full bg-paper-100 dark:bg-ink-700 rounded-full h-1.5 overflow-hidden">
                <div className={`h-full rounded-full ${item.color} transition-all duration-700`} style={{ width: `${item.pct}%` }} />
              </div>
            </div>
            <span className={`text-[11px] sm:text-xs font-black w-10 sm:w-12 text-left flex-shrink-0 font-num tabular-nums ${item.text}`}>
              {fmtDec(item.pct, 1)}٪
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

