  const [period, setPeriod] = useState('today');
  const [stats, setStats] = useState(null);
  const [recentOrders, setRecentOrders] = useState([]);
  const [actionRequiredOrders, setActionRequiredOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [chartMetric, setChartMetric] = useState('revenue');
  const [updatingStatusId, setUpdatingStatusId] = useState(null);

  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined' ? window.innerWidth < MOBILE_BREAKPOINT : false
  );

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  const fetchDashboardData = useCallback(
    async (showSkeleton = true) => {
      if (showSkeleton) setLoading(true);
      else setRefreshing(true);
      try {
        const [statsRes, ordersRes, actionRes] = await Promise.all([
          axios.get('/admin/dashboard/stats'),
          axios.get('/admin/dashboard/recent-orders?limit=10'),
          axios.get('/admin/dashboard/action-required'),
        ]);
        setStats(statsRes.data || {});
        setRecentOrders(ordersRes.data || []);
        setActionRequiredOrders(actionRes.data || []);
        setLastUpdated(new Date());
      } catch (err) {
        showToast('error', 'خطا در بارگذاری داشبورد');
      } finally {
        if (showSkeleton) setLoading(false);
        else setRefreshing(false);
      }
    },
    [showToast]
  );

  useEffect(() => {
    fetchDashboardData();
  }, [fetchDashboardData]);

  // ✅ FIX: paid از این مسیر ممنوع است
  const updateOrderStatus = async (orderId, newStatus) => {
    if (newStatus === 'paid') {
      showToast('error', 'تأیید پرداخت فقط از بخش پرداخت‌ها انجام می‌شود.');
      return;
    }
    if (updatingStatusId) return;
    setUpdatingStatusId(orderId);
    try {
      await axios.put(
        `/admin/orders/${orderId}/status?status=${newStatus}`
      );
      showToast('success', 'وضعیت سفارش به‌روز شد');
      await fetchDashboardData(false);
    } catch (err) {
      const detail = err?.response?.data?.detail;
      showToast(
        'error',
        typeof detail === 'string' ? detail : 'خطا در تغییر وضعیت سفارش'
      );
    } finally {
      setUpdatingStatusId(null);
    }
  };

  const navigateToOrders = (statusFilter) =>
    onNavigate && onNavigate('orders', { statusFilter });
  const navigateToUserDetail = (userId) =>
    onNavigate && onNavigate('user-detail', { userId });
  const navigateToOrderDetail = (orderId) =>
    onNavigate && onNavigate('order-detail', { orderId });
  // ✅ NEW
  const navigateToPayments = () =>
    onNavigate && onNavigate('payments');

  if (loading || !stats) {
    return <DashboardSkeleton />;
  }

  // ============================================================
  //  Derived data
  // ============================================================
